'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Symbol = require( '@stdlib/symbol/ctor' );
var getPrototypeOf = require( '@stdlib/utils/get-prototype-of' );
var descriptor = require( '@stdlib/utils/property-descriptor' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;


// VARIABLES //

var prototype = getPrototypeOf(Float64Array.prototype);
var getLength = descriptor(prototype, 'length').get;
var getBuffer = descriptor(prototype, 'buffer').get;
var getOffset = descriptor(prototype, 'byteOffset').get;
var getTag = descriptor(prototype, Symbol.toStringTag).get;
var getBufferLength = descriptor(ArrayBuffer.prototype, 'byteLength').get;
var MAX = 9007199254740991;


// FUNCTIONS //

/**
* Adds exactly representable indexed integers.
* @private
* @param {integer} a - first integer
* @param {integer} b - second integer
* @throws {RangeError} invalid argument
* @returns {integer} exact sum
*/
function add(a, b) {
	if ((((b > 0) && (a > (MAX - b))) || ((b < 0) && (a < (-MAX - b))))) {
		throw new RangeError('invalid argument. Inexact indexed arithmetic.');
	}
	return (a + b);
}
/**
* Resolves a positive greatest common divisor.
* @private
* @param {integer} a - first magnitude
* @param {integer} b - second magnitude
* @returns {integer} divisor
*/
function gcd(a, b) {
	var r;
	while ((b !== 0)) {
		r = (a % b);
		a = b;
		b = r;
	}
	return a;
}
/**
* Captures and validates an ordinary typed view and exact byte envelope.
* @private
* @param {TypedArray} x - view
* @param {integer} rows - row extent
* @param {integer} cols - column extent
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - offset
* @param {string} dtype - intrinsic type
* @throws {RangeError} invalid argument
* @throws {TypeError} invalid argument
* @returns {Array} backing buffer and half-open envelope
*/
function view(x, rows, cols, r, c, o, dtype) {
	var buffer;
	var bytes;
	var lo;
	var hi;
	var a;
	var b;
	var g;
	if ((getTag.call(x) !== dtype)) {
		throw new TypeError('invalid argument. Incorrect intrinsic typed-array dtype.');
	}
	buffer = getBuffer.call(x);
	getBufferLength.call(buffer);
	if (((!isSafeInteger(r) || !isSafeInteger(c)) || !isSafeInteger(o))) {
		throw new RangeError('invalid argument. Strides and offsets must be safe integers.');
	}
	if ((((rows > 1) && (r === 0)) || ((cols > 1) && (c === 0)))) {
		throw new RangeError('invalid argument. Mutable indexed views must be injective.');
	}
	if (((rows > 1) && (cols > 1))) {
		g = gcd(( (r < 0) ) ? -r : r, ( (c < 0) ) ? -c : c);
		if (((((( (r < 0) ) ? -r : r) / g) < cols) && (((( (c < 0) ) ? -c : c) / g) < rows))) {
			throw new RangeError('invalid argument. Matrix coordinates collide.');
		}
	}
	a = (((rows - 1)) * r);
	b = (((cols - 1)) * c);
	if ((!isSafeInteger(a) || !isSafeInteger(b))) {
		throw new RangeError('invalid argument. Inexact indexed products.');
	}
	lo = add(add(o, ( (a < 0) ) ? a : 0), ( (b < 0) ) ? b : 0);
	hi = add(add(o, ( (a > 0) ) ? a : 0), ( (b > 0) ) ? b : 0);
	if (((lo < 0) || (hi >= getLength.call(x)))) {
		throw new RangeError('invalid argument. Insufficient indexed storage.');
	}
	bytes = ( (dtype === 'Float64Array') ) ? 8 : 4;
	a = (lo * bytes);
	b = (((hi + 1)) * bytes);
	if ((!isSafeInteger(a) || !isSafeInteger(b))) {
		throw new RangeError('invalid argument. Inexact byte envelope.');
	}
	return [
		buffer,
		add(getOffset.call(x), a),
		add(getOffset.call(x), b)
	];
}
/**
* Rejects every pair of overlapping active byte envelopes.
* @private
* @param {Array} views - captured envelopes
* @throws {RangeError} invalid argument
* @returns {void}
*/
function disjoint(views) {
	var a;
	var b;
	var i;
	var j;
	for (i = 0; (i < views.length); i++) {
		a = views[i];
		for (j = (i + 1); (j < views.length); j++) {
			b = views[j];
			if ((((a[0] === b[0]) && (a[1] < b[2])) && (b[1] < a[2]))) {
				throw new RangeError('invalid argument. Active indexed byte envelopes must be disjoint.');
			}
		}
	}
}


// MAIN //

/**
* Validates all active views before any output is modified.
* @private
* @param {integer} N - order
* @param {integer} NB - width
* @param {Int32Array} KB - column-count output
* @param {integer} okb - column-count offset
* @param {Float64Array} A - matrix
* @param {integer} ra - row stride
* @param {integer} ca - column stride
* @param {integer} oa - matrix offset
* @param {Int32Array} P - output pivots
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @param {Float64Array} W - scratch
* @param {integer} rw - scratch row stride
* @param {integer} cw - scratch column stride
* @param {integer} ow - scratch offset
* @returns {void}
*/
function validate(N, NB, KB, okb, A, ra, ca, oa, P, sp, op, W, rw, cw, ow) { // eslint-disable-line max-params
	var kb;
	var a;
	var p;
	var w;
	kb = view(KB, 1, 1, 0, 0, okb, 'Int32Array');
	if ((N === 0)) {
		return;
	}
	a = view(A, N, N, ra, ca, oa, 'Float64Array');
	p = view(P, N, 1, sp, 0, op, 'Int32Array');
	w = view(W, N, NB, rw, cw, ow, 'Float64Array');
	disjoint([
		kb,
		a,
		p,
		w
	]);
}


// EXPORTS //

module.exports = validate;
